import java.io.*;
import java.util.*;

public class easy {

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int how = sc.nextInt();
        sc.nextLine();
        String input = sc.nextLine();

        boolean inside = false;
        String buffer = "";
        List<String> collected = new LinkedList<>();
        int longest = 0;

        for (int idx = 0; idx < input.length(); idx++) {
            char ch = input.charAt(idx);

            switch (ch) {
                case '(':
                    inside = true;
                    longest = Math.max(longest, buffer.length());
                    buffer = "";
                    break;
                case ')':
                    inside = false;
                    if (!buffer.isEmpty()) {
                        collected.add(buffer);
                        buffer = "";
                    }
                    break;
                case '_':
                    if (!inside) {
                        longest = Math.max(longest, buffer.length());
                        buffer = "";
                    } else {
                        if (!buffer.isEmpty()) {
                            collected.add(buffer);
                            buffer = "";
                        }
                    }
                    break;
                default:
                    if (Character.isLetter(ch)) {
                        buffer += ch;
                    }
            }
        }

        longest = Math.max(longest, buffer.length());

        System.out.println(longest + " " + collected.size());
    }
}
